CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'parent' CHECK(role IN ('parent','staff','admin')),email_verified INTEGER NOT NULL DEFAULT 0,approved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS dogs (id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,breed TEXT DEFAULT '',notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY,dog_id TEXT NOT NULL REFERENCES dogs(id),day TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined')),created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(dog_id,day));
CREATE TABLE IF NOT EXISTS schedule (day INTEGER PRIMARY KEY CHECK(day BETWEEN 0 AND 6),destination TEXT NOT NULL DEFAULT '',route TEXT NOT NULL DEFAULT '',running INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS updates (id TEXT PRIMARY KEY,message TEXT NOT NULL,latitude REAL,longitude REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vaccinations (id TEXT PRIMARY KEY,dog_id TEXT NOT NULL REFERENCES dogs(id),object_key TEXT NOT NULL UNIQUE,filename TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS destinations (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,created_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS votes (destination_id TEXT NOT NULL REFERENCES destinations(id),user_id TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(destination_id,user_id));
